    || l.speechAnimation?.npcId === target.id || l.visibleWhenTargetId === target.id
    || aliases[target.id]?.includes(l.id)
    || (target.id === "npc.journalist" && l.id.endsWith(".journalist"))
    || (target.id === "npc.mayor" && l.id.endsWith(".mayor")));
